#!/usr/bin/env python3
"""
Validation script for T14 pipeline outputs.
Validates key outputs: cleaned GTFS stops, cleaned POIs, accessibility scores, and city clusters.
"""

import csv
import json
import os
import sys
from pathlib import Path


def read_csv(path):
    """Read a CSV file and return list of dicts."""
    rows = []
    with open(path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            rows.append(row)
    return rows


def validate_cleaned_stops():
    """Validate cleaned GTFS stops output."""
    path = "outputs/t05_clean_stops.csv"
    rows = read_csv(path)

    checks = []

    # Check 1: File exists and has header
    if os.path.exists(path) and len(rows) > 0:
        required_cols = ['stop_id', 'stop_name', 'stop_lat', 'stop_lon']
        header = rows[0].keys()
        missing_cols = [c for c in required_cols if c not in header]
        if not missing_cols:
            checks.append({
                "check_name": "GTFS stops file has required columns",
                "passed": True,
                "message": "File contains stop_id, stop_name, stop_lat, stop_lon columns"
            })
        else:
            checks.append({
                "check_name": "GTFS stops file has required columns",
                "passed": False,
                "message": f"Missing columns: {missing_cols}"
            })
    else:
        checks.append({
            "check_name": "GTFS stops file exists",
            "passed": False,
            "message": f"File {path} not found"
        })

    # Check 2: All stops have valid coordinates
    if len(rows) > 0:
        invalid_coords = 0
        for row in rows:
            try:
                float(row['stop_lat'])
                float(row['stop_lon'])
            except (ValueError, TypeError):
                invalid_coords += 1
        checks.append({
            "check_name": "GTFS stops have valid coordinates",
            "passed": invalid_coords == 0,
            "message": f"{invalid_coords} stops have invalid coordinates (total: {len(rows)})"
        })

    # Check 3: Stop IDs are unique
    stop_ids = [row['stop_id'] for row in rows]
    unique_stop_ids = len(set(stop_ids))
    checks.append({
        "check_name": "GTFS stops have unique stop IDs",
        "passed": unique_stop_ids == len(stop_ids),
        "message": f"{unique_stop_ids} unique stop IDs found (total rows: {len(stop_ids)})"
    })

    return checks


def validate_cleaned_pois():
    """Validate cleaned POIs output."""
    path = "outputs/t08_pois_clean.csv"
    rows = read_csv(path)

    checks = []

    # Check 1: File exists and has header
    if os.path.exists(path) and len(rows) > 0:
        required_cols = ['qid', 'label', 'poi_type', 'latitude', 'longitude', 'source']
        header = rows[0].keys()
        missing_cols = [c for c in required_cols if c not in header]
        if not missing_cols:
            checks.append({
                "check_name": "POIs file has required columns",
                "passed": True,
                "message": "File contains qid, label, poi_type, latitude, longitude, source columns"
            })
        else:
            checks.append({
                "check_name": "POIs file has required columns",
                "passed": False,
                "message": f"Missing columns: {missing_cols}"
            })
    else:
        checks.append({
            "check_name": "POIs file exists",
            "passed": False,
            "message": f"File {path} not found"
        })

    # Check 2: All POIs have valid coordinates
    if len(rows) > 0:
        invalid_coords = 0
        for row in rows:
            try:
                float(row['latitude'])
                float(row['longitude'])
            except (ValueError, TypeError):
                invalid_coords += 1
        checks.append({
            "check_name": "POIs have valid coordinates",
            "passed": invalid_coords == 0,
            "message": f"{invalid_coords} POIs have invalid coordinates (total: {len(rows)})"
        })

    # Check 3: QIDs are unique
    qids = [row['qid'] for row in rows]
    unique_qids = len(set(qids))
    checks.append({
        "check_name": "POIs have unique QIDs",
        "passed": unique_qids == len(qids),
        "message": f"{unique_qids} unique QIDs found (total rows: {len(qids)})"
    })

    return checks


def validate_accessibility_scores():
    """Validate accessibility scores output."""
    path = "outputs/t10_accessibility_scores.csv"
    rows = read_csv(path)

    checks = []

    # Check 1: File exists and has header
    if os.path.exists(path) and len(rows) > 0:
        required_cols = ['qid', 'label', 'poi_type', 'distance_m', 'n_departures', 'n_routes', 'accessibility_score']
        header = rows[0].keys()
        missing_cols = [c for c in required_cols if c not in header]
        if not missing_cols:
            checks.append({
                "check_name": "Accessibility scores file has required columns",
                "passed": True,
                "message": "File contains qid, label, poi_type, distance_m, n_departures, n_routes, accessibility_score columns"
            })
        else:
            checks.append({
                "check_name": "Accessibility scores file has required columns",
                "passed": False,
                "message": f"Missing columns: {missing_cols}"
            })
    else:
        checks.append({
            "check_name": "Accessibility scores file exists",
            "passed": False,
            "message": f"File {path} not found"
        })

    # Check 2: All accessibility scores are valid floats between 0 and 1
    if len(rows) > 0:
        invalid_scores = 0
        for row in rows:
            try:
                score = float(row['accessibility_score'])
                if not (0 <= score <= 1):
                    invalid_scores += 1
            except (ValueError, TypeError):
                invalid_scores += 1
        checks.append({
            "check_name": "Accessibility scores are valid (0-1 range)",
            "passed": invalid_scores == 0,
            "message": f"{invalid_scores} accessibility scores are invalid (total: {len(rows)})"
        })

    # Check 3: All distance values are valid positive numbers
    if len(rows) > 0:
        invalid_distances = 0
        for row in rows:
            try:
                dist = float(row['distance_m'])
                if dist < 0:
                    invalid_distances += 1
            except (ValueError, TypeError):
                invalid_distances += 1
        checks.append({
            "check_name": "Distance values are valid positive numbers",
            "passed": invalid_distances == 0,
            "message": f"{invalid_distances} distance values are invalid (total: {len(rows)})"
        })

    return checks


def validate_city_clusters():
    """Validate city clusters output."""
    path = "outputs/t13_city_clusters.csv"
    rows = read_csv(path)

    checks = []

    # Check 1: File exists and has header
    if os.path.exists(path) and len(rows) > 0:
        required_cols = ['city_id', 'city_name', 'year', 'cluster_id']
        header = rows[0].keys()
        missing_cols = [c for c in required_cols if c not in header]
        if not missing_cols:
            checks.append({
                "check_name": "City clusters file has required columns",
                "passed": True,
                "message": "File contains city_id, city_name, year, cluster_id columns"
            })
        else:
            checks.append({
                "check_name": "City clusters file has required columns",
                "passed": False,
                "message": f"Missing columns: {missing_cols}"
            })
    else:
        checks.append({
            "check_name": "City clusters file exists",
            "passed": False,
            "message": f"File {path} not found"
        })

    # Check 2: All years are valid integers
    if len(rows) > 0:
        invalid_years = 0
        for row in rows:
            try:
                int(row['year'])
            except (ValueError, TypeError):
                invalid_years += 1
        checks.append({
            "check_name": "City clusters have valid year values",
            "passed": invalid_years == 0,
            "message": f"{invalid_years} years are invalid (total: {len(rows)})"
        })

    # Check 3: Cluster IDs are numeric
    cluster_ids = set()
    for row in rows:
        try:
            int(row['cluster_id'])
            cluster_ids.add(row['cluster_id'])
        except (ValueError, TypeError):
            pass
    checks.append({
        "check_name": "City clusters have numeric cluster IDs",
        "passed": len(cluster_ids) > 0,
        "message": f"Found {len(cluster_ids)} unique cluster IDs"
    })

    return checks


def main():
    """Main validation function."""
    all_checks = []

    all_checks.extend(validate_cleaned_stops())
    all_checks.extend(validate_cleaned_pois())
    all_checks.extend(validate_accessibility_scores())
    all_checks.extend(validate_city_clusters())

    # Write summary to JSON
    output_path = "outputs/t14_validation_summary.json"
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(all_checks, f, indent=2)

    print(f"Validation complete. Summary written to {output_path}")
    print(f"Total checks: {len(all_checks)}")
    passed = sum(1 for c in all_checks if c['passed'])
    print(f"Passed: {passed}, Failed: {len(all_checks) - passed}")

    return 0 if passed == len(all_checks) else 1


if __name__ == "__main__":
    sys.exit(main())

